bad_example:
public async void Procesar() {
    await GuardarAsync(); // si tira excepcion, el caller nunca se entera
}

good_example:
public async Task Procesar() {
    await GuardarAsync(); // el caller puede: await Procesar() y capturar la excepcion con try/catch
}

bad_example:
var acciones = new List<Action>();
for (int i = 0; i < 3; i++) {
    acciones.Add(() => Console.WriteLine(i));
}
// las tres imprimen 3, no 0,1,2

good_example:
var acciones = new List<Action>();
for (int i = 0; i < 3; i++) {
    int copia = i;
    acciones.Add(() => Console.WriteLine(copia));
}
// ahora imprimen 0,1,2 correctamente

bad_example:
var query = db.Usuarios.Where(u => u.Activo);
var total = query.Count();        // ejecuta la query en la DB
foreach (var u in query) { ... }  // ejecuta la query en la DB OTRA VEZ

good_example:
var usuarios = db.Usuarios.Where(u => u.Activo).ToList(); // una sola ejecucion, materializada
var total = usuarios.Count;
foreach (var u in usuarios) { ... }

bad_example:
interface IContador { void Incrementar(); }
struct Contador : IContador {
    public int Valor;
    public void Incrementar() => Valor++;
}
IContador c = new Contador(); // boxing aqui
c.Incrementar();
// c.Valor sigue en 0 vista desde afuera, el incremento fue sobre la copia boxeada

good_example:
class Contador : IContador { // clase en vez de struct: semantica de referencia real
    public int Valor;
    public void Incrementar() => Valor++;
}

bad_example:
var conexion = new SqlConnection(connStr);
conexion.Open();
EjecutarQuery(conexion); // si esto tira excepcion, conexion.Dispose() nunca se llama
conexion.Dispose();

good_example:
using var conexion = new SqlConnection(connStr);
conexion.Open();
EjecutarQuery(conexion); // Dispose() se llama automaticamente al salir del scope, incluso por excepcion

bad_example:
#nullable enable
string? nombre = ObtenerNombre();
Console.WriteLine(nombre.Length); // solo WARNING, compila igual y puede explotar en runtime

good_example:
#nullable enable
string? nombre = ObtenerNombre();
if (nombre is null) throw new InvalidOperationException("nombre requerido");
Console.WriteLine(nombre.Length); // seguro, y sin warning
